// Ported from the public AIcss React source.
// Source: https://www.aicss.dev/components/thinking-state
"use client"

import styles from "./thinking-state.module.css";

export function ThinkingState() {
  return <span className={styles.shimmer}>Thinking</span>;
}

/* Ported from https://www.aicss.dev/components/thinking-state */
.shimmer {
  font-size: 0.8125rem;
  line-height: 1.125rem;
  font-weight: 500;
  color: transparent;
  -webkit-text-fill-color: transparent;
  background: linear-gradient(
    90deg,
    var(--muted-foreground) 0%, var(--muted-foreground) 30%,
    color-mix(in oklch, var(--muted-foreground) 45%, transparent) 45%, color-mix(in oklch, var(--muted-foreground) 45%, transparent) 55%,
    var(--muted-foreground) 70%, var(--muted-foreground) 100%
  );
  background-size: 300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  animation: label-shine 2.25s cubic-bezier(0.25, 0.1, 0.25, 1) infinite;
}
@keyframes label-shine {
  0%, 18% { background-position: 100% 0; }
  82%, 100% { background-position: 0% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .shimmer {
    animation: none !important;
    transition-duration: 0.01ms !important;
  }
}
